import { Select } from "@components/select";
import { clsx } from "clsx";

import { useTable } from "../hooks/use-table";
import { type TablePageSizeSelectProps } from "../table.types";
import { TableClasses } from "../table.styles";

export const TablePageSizeSelect = ({
  options,
  className,
  renderLabel = (pageSize) => `Show ${pageSize}`,
  width,
  ...props
}: TablePageSizeSelectProps) => {
  const { state, setPageSize } = useTable();
  const { pagination } = state;

  return (
    <Select
      className={clsx(TableClasses.pageSizeSelect, className)}
      showSelectedIndicator={false}
      style={{ width }}
      value={pagination.pageSize.toString()}
      onValueChange={(value) => {
        setPageSize(Number(value));
      }}
      {...props}
    >
      <Select.Trigger aria-label={props["aria-label"] || "Select page size"}>
        <Select.Value />
        <Select.Icon />
      </Select.Trigger>
      <Select.Content>
        {options?.map((pageSize) => (
          <Select.Item
            key={pageSize}
            data-testid={`page-size-${pageSize}`}
            value={pageSize.toString()}
          >
            {renderLabel(pageSize)}
          </Select.Item>
        ))}
      </Select.Content>
    </Select>
  );
};

TablePageSizeSelect.displayName = "Table.PageSizeSelect";
